import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabaseClient';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  InputAdornment,
  Grid,
  Card,
  CardContent,
  Chip,
  Container,
  CircularProgress,
  IconButton,
  Alert,
  Stack,
  useTheme
} from '@mui/material';
import {
  ArrowBack as ArrowBackIcon,
  Search as SearchIcon,
  Money as MoneyIcon,
  Receipt as ReceiptIcon,
  Description as DescriptionIcon,
  Person as PersonIcon,
  Inbox as InboxIcon,
  WaterDrop as WaterIcon,
  Info as InfoIcon,
  Login as LoginIcon
} from '@mui/icons-material';
import MobileBottomBar from './common/MobileBottomBar';

const CheckUnclaimedChecks = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const [checks, setChecks] = useState([]);
  const [filteredChecks, setFilteredChecks] = useState([]);
  const [error, setError] = useState('');
  const [searched, setSearched] = useState(false);

  // Fetch all ready to claim checks on component mount
  useEffect(() => {
    fetchReadyToClaimChecks();
  }, []);

  // Filter checks when search term changes
  useEffect(() => {
    if (searched) {
      filterChecks();
    }
  }, [searchTerm, checks, searched]);

  const fetchReadyToClaimChecks = async () => {
    setLoading(true);
    setError('');
    setSearched(true);
    
    try {
      const { data, error } = await supabase
        .from('elogbook_transactions')
        .select('*')
        .eq('status', 'ready_to_claim')
        .not('check_number', 'is', null)
        .order('check_created_date', { ascending: false, nullsFirst: false });

      if (error) throw error;

      setChecks(data || []);
      setFilteredChecks(data || []);
    } catch (err) {
      console.error('Error fetching checks:', err);
      setError('Failed to load unclaimed checks. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const filterChecks = () => {
    if (!searchTerm.trim()) {
      setFilteredChecks(checks);
      return;
    }

    const term = searchTerm.toLowerCase();
    const filtered = checks.filter(check => {
      const payee = (check.voucher_payee || check.payee_name || '').toLowerCase();
      const particulars = (check.voucher_particulars || '').toLowerCase();
      const checkNumber = (check.check_number || '').toLowerCase();
      const cafoaNumber = (check.cafoa_number || '').toLowerCase();
      const dvNumber = (check.dv_number || '').toLowerCase();

      return (
        payee.includes(term) ||
        particulars.includes(term) ||
        checkNumber.includes(term) ||
        cafoaNumber.includes(term) ||
        dvNumber.includes(term)
      );
    });

    setFilteredChecks(filtered);
  };

  const handleSearch = (e) => {
    e.preventDefault();
    filterChecks();
  };

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'grey.100', py: 4 }}>
      <Container maxWidth="lg">
        {/* Header */}
        <Box sx={{ mb: 4 }}>
          <Button 
            startIcon={<ArrowBackIcon />} 
            onClick={() => navigate('/')}
            sx={{ mb: 2 }}
          >
            Back to Home
          </Button>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 1 }}>
            <MoneyIcon color="primary" sx={{ fontSize: 40 }} />
            <Typography variant="h4" fontWeight="bold" color="text.primary">
              Check Unclaimed Checks
            </Typography>
          </Box>
          <Typography variant="body1" color="text.secondary">
            View and search for checks ready to claim from the e-Logbook system
          </Typography>
        </Box>

        {/* Search Section */}
        <Paper elevation={0} sx={{ p: 3, mb: 4, borderRadius: 2 }}>
          <form onSubmit={handleSearch}>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} md={10}>
                <TextField
                  fullWidth
                  placeholder="Search by beneficiary name or description..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  disabled={loading}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon color="action" />
                      </InputAdornment>
                    ),
                  }}
                  sx={{ bgcolor: 'background.paper' }}
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <Button
                  fullWidth
                  type="submit"
                  variant="contained"
                  size="large"
                  disabled={loading}
                  startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <SearchIcon />}
                  sx={{ height: 56 }}
                >
                  {loading ? 'Loading...' : 'Search'}
                </Button>
              </Grid>
            </Grid>
          </form>
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
        </Paper>

        {/* Results Section */}
        {searched && !loading && (
          <Box>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
              <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <ReceiptIcon color="primary" />
                Ready to Claim Checks
              </Typography>
              <Chip 
                label={`${filteredChecks.length} ${filteredChecks.length === 1 ? 'check' : 'checks'} found`}
                color="primary"
                variant="outlined"
              />
            </Box>

            {filteredChecks.length === 0 ? (
              <Paper sx={{ p: 6, textAlign: 'center', borderRadius: 2 }}>
                <InboxIcon sx={{ fontSize: 60, color: 'text.secondary', mb: 2 }} />
                <Typography variant="h6" color="text.secondary">No unclaimed checks found</Typography>
                <Typography color="text.secondary">All checks have been claimed or are not yet ready</Typography>
              </Paper>
            ) : (
              <Stack spacing={2}>
                {filteredChecks.map((check) => (
                  <Card key={check.id} variant="outlined" sx={{ '&:hover': { boxShadow: 3, borderColor: 'primary.main' }, transition: 'all 0.2s' }}>
                    <CardContent>
                      <Grid container spacing={2} alignItems="center">
                        <Grid item xs={12} md={4}>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                            <PersonIcon color="action" />
                            <Box>
                              <Typography variant="caption" color="text.secondary" display="block">
                                Beneficiary Name
                              </Typography>
                              <Typography variant="subtitle1" fontWeight="bold">
                                {check.voucher_payee || check.payee_name || '—'}
                              </Typography>
                            </Box>
                          </Box>
                        </Grid>
                        <Grid item xs={12} md={8}>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                            <DescriptionIcon color="action" />
                            <Box>
                              <Typography variant="caption" color="text.secondary" display="block">
                                Description
                              </Typography>
                              <Typography variant="body1">
                                {check.voucher_particulars || check.check_remarks || check.voucher_type || '—'}
                              </Typography>
                            </Box>
                          </Box>
                        </Grid>
                      </Grid>
                    </CardContent>
                  </Card>
                ))}
              </Stack>
            )}
          </Box>
        )}
      </Container>

      {/* Sticky Mobile Bottom Navigation */}
      <MobileBottomBar
        items={[
          { name: 'Home', icon: <InfoIcon />, path: '/' },
          { name: 'Water Bills', icon: <WaterIcon />, path: '/check-water-bills' },
          { name: 'Unclaimed Checks', icon: <ReceiptIcon />, path: '/check-unclaimed-checks' },
          { name: 'Staff Portal', icon: <LoginIcon />, path: '/login' }
        ]}
        currentPath="/check-unclaimed-checks"
        onNavigate={(path) => navigate(path)}
      />
    </Box>
  );
};

export default CheckUnclaimedChecks;

