import React, { useState, useEffect } from 'react';
import { Snackbar, Alert, Dialog, DialogTitle, DialogContent, DialogActions, Button, Typography, Slide } from '@mui/material';

let notificationCallback = null;

export const showNotification = (message, type = 'info', duration = 3000) => {
  if (notificationCallback) {
    notificationCallback(message, type, duration);
  }
};

export const showConfirmation = (message, description = '') => {
  return new Promise((resolve) => {
    if (notificationCallback) {
      notificationCallback(message, 'confirm', 0, (confirmed) => {
        resolve(confirmed);
      }, description);
    } else {
      resolve(false);
    }
  });
};

const Notification = () => {
  const [open, setOpen] = useState(false);
  const [notification, setNotification] = useState({ message: '', type: 'info', duration: 3000 });
  const [confirmation, setConfirmation] = useState(null);

  useEffect(() => {
    notificationCallback = (message, type, duration, callback, description) => {
      if (type === 'confirm') {
        setConfirmation({ message, description, callback });
      } else {
        setNotification({ message, type, duration: duration ?? 3000 });
        setOpen(true);
      }
    };
    return () => {
      notificationCallback = null;
    };
  }, []);

  const handleClose = () => {
    setOpen(false);
  };

  const handleConfirm = (confirmed) => {
    if (confirmation && confirmation.callback) {
      confirmation.callback(confirmed);
    }
    setConfirmation(null);
  };

  const alertRole = notification.type === 'error' ? 'alert' : 'status';
  const alertLive = notification.type === 'error' ? 'assertive' : 'polite';

  return (
    <>
      <Snackbar
        open={open}
        autoHideDuration={notification.duration || 3000}
        onClose={handleClose}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
        TransitionComponent={(props) => <Slide {...props} direction="left" />}
      >
        <Alert
          severity={notification.type}
          variant="filled"
          sx={{ width: '100%' }}
          role={alertRole}
          aria-live={alertLive}
        >
          {notification.message}
        </Alert>
      </Snackbar>

      <Dialog
        open={Boolean(confirmation)}
        onClose={() => handleConfirm(false)}
        aria-describedby="global-confirmation-description"
      >
        <DialogTitle>Confirm Action</DialogTitle>
        <DialogContent>
          <Typography id="global-confirmation-description">{confirmation?.message}</Typography>
          {confirmation?.description && (
            <Typography sx={{ mt: 1 }} color="text.secondary">{confirmation.description}</Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => handleConfirm(false)}>Cancel</Button>
          <Button onClick={() => handleConfirm(true)} variant="contained" color="primary">Confirm</Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default Notification;
