import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Routes, Route } from 'react-router-dom';
import { authService } from '../../../authService';
import LogBookHome from './pages/LogBookHome';
import DocumentTracking from './pages/DocumentTracking';
import LogBookReports from './pages/LogBookReports';
import LogBookSettings from './pages/LogBookSettings';
import BIRForms from './pages/BIRForms';
import Suppliers from './pages/Suppliers';
import ProfileModal from '../../modals/ProfileModal';
import SettingsModal from '../../modals/SettingsModal';
import MobileBottomBar from '../../common/MobileBottomBar';
import {
  Box,
  Drawer,
  AppBar,
  Toolbar,
  List,
  Typography,
  Divider,
  IconButton,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Avatar,
  useTheme,
  useMediaQuery,
  CssBaseline,
  Menu,
  MenuItem
} from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard,
  FactCheck,
  Assessment,
  Settings as SettingsIcon,
  ArrowBack,
  MenuBook,
  Logout,
  Person,
  Description,
  PeopleAlt as PeopleAltIcon
} from '@mui/icons-material';

const drawerWidth = 280;

const ELogBookDashboard = ({ onLogout }) => {
  const [user, setUser] = useState(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  useEffect(() => {
    const currentUser = authService.getUserSession();
    if (!currentUser) {
      navigate('/login');
    } else {
      setUser(currentUser);
    }
    document.title = 'e-LogBook System - LGU Concepcion';
  }, [navigate]);

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    handleMenuClose();
    authService.logout();
    if (onLogout) {
      onLogout();
    }
    navigate('/login', { replace: true });
  };

  const handleBackToPortal = () => {
    sessionStorage.removeItem('currentSystem');
    navigate('/portal');
  };

  const handleProfileClick = () => {
    handleMenuClose();
    setShowProfileModal(true);
  };

  const handleSettingsClick = () => {
    handleMenuClose();
    setShowSettingsModal(true);
  };

  const handleProfileUpdate = (updatedUser) => {
    setUser(updatedUser);
    authService.setUserSession(updatedUser);
  };

  const getMenuItems = () => {
    const allMenuItems = [
      { name: 'Dashboard', icon: <Dashboard />, path: '/portal/e-logbook/home' },
      { name: 'Document Tracking', icon: <FactCheck />, path: '/portal/e-logbook/tracking' },
      { name: 'BIR Forms', icon: <Description />, path: '/portal/e-logbook/bir-forms' },
      { name: 'Suppliers', icon: <PeopleAltIcon />, path: '/portal/e-logbook/suppliers' },
      { name: 'Reports', icon: <Assessment />, path: '/portal/e-logbook/reports' },
      { name: 'Settings', icon: <SettingsIcon />, path: '/portal/e-logbook/settings' }
    ];

    if (user?.role === 'user') {
      return allMenuItems.filter(item => item.name === 'Dashboard');
    }

    return allMenuItems;
  };

  const menuItems = getMenuItems();

  const drawer = (
    <div>
      <Toolbar sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        px: 2, 
        bgcolor: 'var(--bs-primary)', 
        color: '#fff',
        minHeight: 64
      }}>
        <MenuBook sx={{ mr: 2 }} />
        <Box>
          <Typography variant="subtitle1" fontWeight="bold">
            e-LogBook
          </Typography>
          <Typography variant="caption" sx={{ opacity: 0.8 }}>
            Document Tracking
          </Typography>
        </Box>
      </Toolbar>
      <Divider />
      <Box sx={{ p: 2 }}>
        <ListItemButton 
          onClick={handleBackToPortal} 
          sx={{ 
            borderRadius: 1, 
            mb: 2, 
            border: '1px solid', 
            borderColor: 'divider',
            '&:hover': { bgcolor: 'action.hover' }
          }}
        >
          <ListItemIcon>
            <ArrowBack />
          </ListItemIcon>
          <ListItemText primary="Back to Portal" />
        </ListItemButton>
      </Box>
      <Divider />
      <List>
        {menuItems.map((item) => (
          <ListItem key={item.path} disablePadding>
            <ListItemButton
              selected={location.pathname === item.path}
              onClick={() => {
                navigate(item.path);
                if (isMobile) setMobileOpen(false);
              }}
              sx={{
                mx: 1,
                borderRadius: 1,
                mb: 0.5,
                '&.Mui-selected': {
                  bgcolor: 'rgba(var(--system-color-rgb), 0.15)',
                  color: 'var(--bs-primary)',
                  '& .MuiListItemIcon-root': {
                    color: 'var(--bs-primary)',
                  },
                  '&:hover': {
                    bgcolor: 'rgba(var(--system-color-rgb), 0.25)',
                  },
                },
              }}
            >
              <ListItemIcon sx={{ color: location.pathname === item.path ? 'inherit' : 'text.secondary' }}>
                {item.icon}
              </ListItemIcon>
              <ListItemText primary={item.name} />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
      <Box sx={{ flexGrow: 1 }} />
      <Divider />
      <Box sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
        <Avatar 
          sx={{ bgcolor: 'primary.main', cursor: 'pointer' }}
          onClick={handleMenuOpen}
        >
          {user?.firstname?.charAt(0)}{user?.lastname?.charAt(0)}
        </Avatar>
        <Box sx={{ overflow: 'hidden' }}>
          <Typography variant="subtitle2" noWrap>
            {user?.firstname} {user?.lastname}
          </Typography>
          <Typography variant="caption" color="text.secondary" noWrap>
            {user?.role}
          </Typography>
        </Box>
        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleMenuClose}
          transformOrigin={{ horizontal: 'left', vertical: 'bottom' }}
          anchorOrigin={{ horizontal: 'left', vertical: 'top' }}
        >
          <MenuItem onClick={handleProfileClick}>
            <ListItemIcon><Person fontSize="small" /></ListItemIcon>
            Profile
          </MenuItem>
          <MenuItem onClick={handleSettingsClick}>
            <ListItemIcon><SettingsIcon fontSize="small" /></ListItemIcon>
            Settings
          </MenuItem>
          <Divider />
          <MenuItem onClick={handleLogout}>
            <ListItemIcon><Logout fontSize="small" /></ListItemIcon>
            Logout
          </MenuItem>
        </Menu>
      </Box>
    </div>
  );

  if (!user) return null;

  return (
    <SystemThemeProvider systemId="e-logbook">
    <Box sx={{ display: 'flex' }}>
      <CssBaseline />
      <AppBar
        position="fixed"
        sx={{
          width: { md: `calc(100% - ${drawerWidth}px)` },
          ml: { md: `${drawerWidth}px` },
          display: { md: 'none' },
          bgcolor: 'var(--bs-primary)'
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { md: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" noWrap component="div">
            e-LogBook System
          </Typography>
        </Toolbar>
      </AppBar>
      <Box
        component="nav"
        sx={{ width: { md: drawerWidth }, flexShrink: { md: 0 } }}
      >
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{ keepMounted: true }}
          sx={{
            display: { xs: 'block', md: 'none' },
            '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
          }}
        >
          {drawer}
        </Drawer>
        <Drawer
          variant="permanent"
          sx={{
            display: { xs: 'none', md: 'block' },
            '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
          }}
          open
        >
          {drawer}
        </Drawer>
      </Box>
      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: { xs: 2, sm: 3 },
          pb: { xs: 10, md: 3 },
          width: { md: `calc(100% - ${drawerWidth}px)` },
          bgcolor: 'background.default',
          minHeight: '100vh',
          mt: { xs: 8, md: 0 }
        }}
      >
        <Routes>
          <Route path="home" element={<LogBookHome user={user} />} />
          <Route path="tracking" element={<DocumentTracking user={user} />} />
          <Route path="bir-forms" element={<BIRForms user={user} />} />
          <Route path="suppliers" element={<Suppliers user={user} />} />
          <Route path="reports" element={<LogBookReports user={user} />} />
          <Route path="settings" element={<LogBookSettings user={user} />} />
          <Route path="*" element={<LogBookHome user={user} />} />
        </Routes>
      </Box>

      {/* Sticky Mobile Bottom Navigation */}
      <MobileBottomBar
        items={menuItems}
        currentPath={location.pathname}
        onNavigate={(path) => navigate(path)}
        onToggleMenu={handleDrawerToggle}
        isMenuOpen={mobileOpen}
        themeColor="var(--bs-primary)"
      />

      {/* Modals */}
      <ProfileModal
        user={user}
        isOpen={showProfileModal}
        onClose={() => setShowProfileModal(false)}
        onUpdate={handleProfileUpdate}
      />
      <SettingsModal
        isOpen={showSettingsModal}
        onClose={() => setShowSettingsModal(false)}
      />
    </Box>

    </SystemThemeProvider>
  );
};

export default ELogBookDashboard;
import { SystemThemeProvider } from '../../../hooks/useSystemTheme'
