import React from 'react';
import { Box, Paper, Typography, useTheme } from '@mui/material';
import { Menu as MenuIcon } from '@mui/icons-material';

/**
 * Reusable Mobile Bottom Navigation Bar
 * 
 * @param {Array} items - Array of navigation items { name, icon, path }
 * @param {string} currentPath - Active location pathname
 * @param {function} onNavigate - Callback when an item is selected (path) => void
 * @param {function} onToggleMenu - Callback when the "Menu" drawer button is tapped
 * @param {string} [themeColor] - Custom brand color for active items (optional)
 * @param {boolean} [isMenuOpen] - Whether the mobile drawer menu is currently open
 */
const MobileBottomBar = ({
  items = [],
  currentPath = '',
  onNavigate,
  onToggleMenu,
  themeColor,
  isMenuOpen = false
}) => {
  const theme = useTheme();
  
  // Show top 4 items on bottom bar + Menu button
  const primaryItems = items.slice(0, 4);
  const activeColor = themeColor || theme.palette.primary.main;
  
  // Check if active path is in primary items or in remaining menu items
  const isPrimaryActive = (path) => currentPath === path;
  const isOtherActive = items.slice(4).some(item => currentPath === item.path);

  return (
    <Paper
      elevation={12}
      className="mobile-bottom-nav"
      sx={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        zIndex: 1200,
        display: { xs: 'flex', md: 'none' },
        bgcolor: 'background.paper',
        borderTop: '1px solid',
        borderColor: 'divider',
        boxShadow: '0 -4px 20px rgba(0, 0, 0, 0.08)',
        justifyContent: 'space-around',
        alignItems: 'center',
        py: 0.75,
        px: 0.5,
        height: 64,
        WebkitBackdropFilter: 'blur(10px)',
        backdropFilter: 'blur(10px)',
        bgcolor: theme.palette.mode === 'dark' ? 'rgba(18, 18, 18, 0.95)' : 'rgba(255, 255, 255, 0.95)'
      }}
    >
      {primaryItems.map((item) => {
        const active = isPrimaryActive(item.path);
        return (
          <Box
            key={item.path}
            onClick={() => onNavigate && onNavigate(item.path)}
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
              cursor: 'pointer',
              color: active ? activeColor : 'text.secondary',
              py: 0.5,
              px: 0.5,
              borderRadius: 2,
              transition: 'all 0.2s ease-in-out',
              userSelect: 'none',
              '&:active': { transform: 'scale(0.92)' }
            }}
          >
            <Box 
              sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                p: 0.5,
                borderRadius: 1.5,
                bgcolor: active ? `rgba(${theme.palette.mode === 'dark' ? '255,255,255' : '0,0,0'}, 0.06)` : 'transparent',
                '& .MuiSvgIcon-root': {
                  fontSize: '1.4rem',
                  transition: 'transform 0.2s',
                  transform: active ? 'scale(1.1)' : 'scale(1)'
                }
              }}
            >
              {item.icon}
            </Box>
            <Typography
              variant="caption"
              sx={{
                fontSize: '0.68rem',
                fontWeight: active ? 700 : 500,
                color: 'inherit',
                mt: 0.2,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                maxWidth: '100%',
                lineHeight: 1.1
              }}
            >
              {item.name}
            </Typography>
          </Box>
        );
      })}

      {/* Menu / More button */}
      <Box
        onClick={onToggleMenu}
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          flex: 1,
          cursor: 'pointer',
          color: (isMenuOpen || isOtherActive) ? activeColor : 'text.secondary',
          py: 0.5,
          px: 0.5,
          borderRadius: 2,
          transition: 'all 0.2s ease-in-out',
          userSelect: 'none',
          '&:active': { transform: 'scale(0.92)' }
        }}
      >
        <Box 
          sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            p: 0.5,
            borderRadius: 1.5,
            bgcolor: (isMenuOpen || isOtherActive) ? `rgba(${theme.palette.mode === 'dark' ? '255,255,255' : '0,0,0'}, 0.06)` : 'transparent'
          }}
        >
          <MenuIcon 
            sx={{ 
              fontSize: '1.4rem',
              transition: 'transform 0.2s',
              transform: (isMenuOpen || isOtherActive) ? 'scale(1.1)' : 'scale(1)'
            }} 
          />
        </Box>
        <Typography
          variant="caption"
          sx={{
            fontSize: '0.68rem',
            fontWeight: (isMenuOpen || isOtherActive) ? 700 : 500,
            color: 'inherit',
            mt: 0.2,
            lineHeight: 1.1
          }}
        >
          Menu
        </Typography>
      </Box>
    </Paper>
  );
};

export default MobileBottomBar;
