import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Routes, Route } from 'react-router-dom';
import { authService } from '../../../authService';
import RuralHealthHome from './pages/RuralHealthHome';
import Services from './pages/Services';
import OrderOfPayments from './pages/OrderOfPayments';
import RHUReports from './pages/RHUReports';
import RHUSettings from './pages/RHUSettings';
import RHUAccessLogin from './RHUAccessLogin';
import ProfileModal from '../../modals/ProfileModal';
import SettingsModal from '../../modals/SettingsModal';
import MobileBottomBar from '../../common/MobileBottomBar';
import {
  Box,
  Drawer,
  AppBar,
  Toolbar,
  List,
  Typography,
  Divider,
  IconButton,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Avatar,
  useTheme,
  useMediaQuery,
  CssBaseline,
  Menu,
  MenuItem
} from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard,
  MedicalServices,
  Receipt,
  Assessment,
  Settings as SettingsIcon,
  ArrowBack,
  HealthAndSafety,
  Logout,
  Person
} from '@mui/icons-material';

const drawerWidth = 280;

const RuralHealthDashboard = ({ onLogout }) => {
  const [user, setUser] = useState(null);
  const [accessType, setAccessType] = useState(null); // 'login' or 'code'
  const [showAccessLogin, setShowAccessLogin] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  useEffect(() => {
    // Check for normal login first
    const currentUser = authService.getUserSession();
    
    if (currentUser) {
      // User is logged in normally
      setUser(currentUser);
      setAccessType('login');
      setShowAccessLogin(false);
    } else {
      // Check for access code session
      const accessSession = sessionStorage.getItem('rhu_access');
      
      if (accessSession) {
        try {
          const access = JSON.parse(accessSession);
          // Create a staff user object
          setUser({
            firstname: 'RHU',
            lastname: 'Staff',
            role: 'RHU Staff',
            accessCode: access.code
          });
          setAccessType('code');
          setShowAccessLogin(false);
        } catch (error) {
          // Invalid session, show access login
          setShowAccessLogin(true);
        }
      } else {
        // No authentication, show access code login
        setShowAccessLogin(true);
      }
    }
    document.title = 'Rural Health Unit - LGU Concepcion';
  }, [navigate]);

  useEffect(() => {
    if (location.pathname === '/portal/rural-health' || location.pathname === '/portal/rural-health/') {
      // Redirect based on access type
      if (accessType === 'code') {
        navigate('/portal/rural-health/order-payments', { replace: true });
      } else if (accessType === 'login') {
        navigate('/portal/rural-health/dashboard', { replace: true });
      }
    }
    
    // Prevent code users from accessing dashboard
    if (accessType === 'code' && location.pathname === '/portal/rural-health/dashboard') {
      navigate('/portal/rural-health/order-payments', { replace: true });
    }
  }, [location.pathname, navigate, accessType]);

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    handleMenuClose();
    // Clear access code session if exists
    sessionStorage.removeItem('rhu_access');
    
    // Clear normal auth session
    authService.logout();
    
    if (onLogout) {
      onLogout();
    }
    
    // Code users should see access login again, normal users go to login
    if (accessType === 'code') {
      setUser(null);
      setAccessType(null);
      setShowAccessLogin(true);
    } else {
      navigate('/login', { replace: true });
    }
  };

  const handleBackToPortal = () => {
    if (accessType === 'login') {
      navigate('/portal');
    } else {
      // Code users can't go to portal, logout instead
      handleLogout();
    }
  };

  const handleAccessGranted = (accessUser) => {
    setUser(accessUser);
    setAccessType('code');
    setShowAccessLogin(false);
    navigate('/portal/rural-health/order-payments');
  };

  const handleProfileClick = () => {
    handleMenuClose();
    setShowProfileModal(true);
  };

  const handleSettingsClick = () => {
    handleMenuClose();
    setShowSettingsModal(true);
  };

  const handleProfileUpdate = (updatedUser) => {
    setUser(updatedUser);
    authService.setUserSession(updatedUser);
  };

  const menuItems = [
    { name: 'Dashboard', icon: <Dashboard />, path: '/portal/rural-health/dashboard' },
    { name: 'Services', icon: <MedicalServices />, path: '/portal/rural-health/services' },
    { name: 'Order of Payments', icon: <Receipt />, path: '/portal/rural-health/order-payments' },
    { name: 'Report', icon: <Assessment />, path: '/portal/rural-health/report' },
    { name: 'Settings', icon: <SettingsIcon />, path: '/portal/rural-health/settings' }
  ];

  // Filter menu items based on access type
  const filteredMenuItems = accessType === 'code' 
    ? menuItems.filter(item => item.name !== 'Dashboard')
    : menuItems;

  const drawer = (
    <div>
      <Toolbar sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        px: 2, 
        bgcolor: 'error.main', 
        color: 'error.contrastText',
        minHeight: 64
      }}>
        <HealthAndSafety sx={{ mr: 2 }} />
        <Box>
          <Typography variant="subtitle1" fontWeight="bold">
            Rural Health Unit
          </Typography>
          <Typography variant="caption" sx={{ opacity: 0.8 }}>
            LGU Concepcion
          </Typography>
        </Box>
      </Toolbar>
      <Divider />
      <Box sx={{ p: 2 }}>
        <ListItemButton 
          onClick={handleBackToPortal} 
          sx={{ 
            borderRadius: 1, 
            mb: 2, 
            border: '1px solid', 
            borderColor: 'divider',
            '&:hover': { bgcolor: 'action.hover' }
          }}
        >
          <ListItemIcon>
            <ArrowBack />
          </ListItemIcon>
          <ListItemText primary={accessType === 'login' ? 'Back to Portal' : 'Exit System'} />
        </ListItemButton>
      </Box>
      <Divider />
      <List>
        {filteredMenuItems.map((item) => (
          <ListItem key={item.path} disablePadding>
            <ListItemButton
              selected={location.pathname === item.path}
              onClick={() => {
                navigate(item.path);
                if (isMobile) setMobileOpen(false);
              }}
              sx={{
                mx: 1,
                borderRadius: 1,
                mb: 0.5,
                '&.Mui-selected': {
                  bgcolor: 'error.light',
                  color: 'error.contrastText',
                  '& .MuiListItemIcon-root': {
                    color: 'error.contrastText',
                  },
                  '&:hover': {
                    bgcolor: 'error.main',
                  },
                },
              }}
            >
              <ListItemIcon sx={{ color: location.pathname === item.path ? 'inherit' : 'text.secondary' }}>
                {item.icon}
              </ListItemIcon>
              <ListItemText primary={item.name} />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
      <Box sx={{ flexGrow: 1 }} />
      <Divider />
      <Box sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
        <Avatar 
          sx={{ bgcolor: 'secondary.main', cursor: 'pointer' }}
          onClick={handleMenuOpen}
        >
          {user?.firstname?.charAt(0)}{user?.lastname?.charAt(0)}
        </Avatar>
        <Box sx={{ overflow: 'hidden' }}>
          <Typography variant="subtitle2" noWrap>
            {user?.firstname} {user?.lastname}
          </Typography>
          <Typography variant="caption" color="text.secondary" noWrap>
            {user?.role}
          </Typography>
        </Box>
        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleMenuClose}
          transformOrigin={{ horizontal: 'left', vertical: 'bottom' }}
          anchorOrigin={{ horizontal: 'left', vertical: 'top' }}
        >
          {accessType === 'login' && (
            <div>
              <MenuItem onClick={handleProfileClick}>
                <ListItemIcon><Person fontSize="small" /></ListItemIcon>
                Profile
              </MenuItem>
              <MenuItem onClick={handleSettingsClick}>
                <ListItemIcon><SettingsIcon fontSize="small" /></ListItemIcon>
                Settings
              </MenuItem>
              <Divider />
            </div>
          )}
          <MenuItem onClick={handleLogout}>
            <ListItemIcon><Logout fontSize="small" /></ListItemIcon>
            Logout
          </MenuItem>
        </Menu>
      </Box>
    </div>
  );

  // Show access code login if needed
  if (showAccessLogin) {
    return <RHUAccessLogin onAccessGranted={handleAccessGranted} />;
  }

  if (!user) return null;

  return (
    <Box sx={{ display: 'flex' }}>
      <CssBaseline />
      <AppBar
        position="fixed"
        sx={{
          width: { md: `calc(100% - ${drawerWidth}px)` },
          ml: { md: `${drawerWidth}px` },
          display: { md: 'none' },
          bgcolor: 'error.main'
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { md: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" noWrap component="div">
            Rural Health Unit
          </Typography>
        </Toolbar>
      </AppBar>
      <Box
        component="nav"
        sx={{ width: { md: drawerWidth }, flexShrink: { md: 0 } }}
      >
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{ keepMounted: true }}
          sx={{
            display: { xs: 'block', md: 'none' },
            '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
          }}
        >
          {drawer}
        </Drawer>
        <Drawer
          variant="permanent"
          sx={{
            display: { xs: 'none', md: 'block' },
            '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
          }}
          open
        >
          {drawer}
        </Drawer>
      </Box>
      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: { xs: 2, sm: 3 },
          pb: { xs: 10, md: 3 },
          width: { md: `calc(100% - ${drawerWidth}px)` },
          bgcolor: 'background.default',
          minHeight: '100vh',
          mt: { xs: 8, md: 0 }
        }}
      >
        <Routes>
          <Route index element={<RuralHealthHome user={user} />} />
          <Route path="dashboard" element={<RuralHealthHome user={user} />} />
          <Route path="services" element={<Services />} />
          <Route path="order-payments" element={<OrderOfPayments />} />
          <Route path="report" element={<RHUReports />} />
          <Route path="settings" element={<RHUSettings user={user} />} />
        </Routes>
      </Box>

      {/* Sticky Mobile Bottom Navigation */}
      <MobileBottomBar
        items={filteredMenuItems}
        currentPath={location.pathname}
        onNavigate={(path) => navigate(path)}
        onToggleMenu={handleDrawerToggle}
        isMenuOpen={mobileOpen}
        themeColor="error.main"
      />

      {/* Modals */}
      <ProfileModal
        user={user}
        isOpen={showProfileModal}
        onClose={() => setShowProfileModal(false)}
        onUpdate={handleProfileUpdate}
      />
      <SettingsModal
        isOpen={showSettingsModal}
        onClose={() => setShowSettingsModal(false)}
      />
    </Box>

  );
};

export default RuralHealthDashboard;
