import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { customerService } from '../services/customerService';
import { billingService } from '../services/billingService';
import { paymentService } from '../services/paymentService';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  Avatar,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  ListItemButton,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Chip,
  IconButton
} from '@mui/material';
import {
  People,
  MonetizationOn,
  Receipt,
  Warning,
  PersonAdd,
  Description,
  Payment,
  Assessment,
  Refresh,
  ChevronRight,
  Person,
  Close,
  CalendarToday,
  CheckCircle,
  Bolt
} from '@mui/icons-material';

const DashboardHome = ({ user }) => {
  const navigate = useNavigate();
  const [recentCustomers, setRecentCustomers] = useState([]);
  const [recentPayments, setRecentPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [statsLoading, setStatsLoading] = useState(true);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [selectedPayment, setSelectedPayment] = useState(null);
  const [stats, setStats] = useState({
    totalCustomers: 0,
    activeCustomers: 0,
    monthlyRevenue: 0,
    pendingBills: 0,
    overdueAccounts: 0,
    todayCollection: 0
  });
  
  useEffect(() => {
    loadRecentData();
    loadStatistics();
  }, []);
  
  const loadRecentData = async () => {
    setLoading(true);
    try {
      const [customersResult, paymentsResult] = await Promise.all([
        customerService.getRecentCustomers(5),
        paymentService.getRecentPayments(5)
      ]);
      
      if (customersResult.success) setRecentCustomers(customersResult.data || []);
      if (paymentsResult.success) setRecentPayments(paymentsResult.data || []);
    } catch (err) {
      console.error('Error loading recent data:', err);
    }
    setLoading(false);
  };

  const loadStatistics = async () => {
    setStatsLoading(true);
    try {
      const [customerStats, paymentStats, billsResult] = await Promise.all([
        customerService.getCustomerStats(),
        paymentService.getPaymentStats(),
        billingService.getBills(1, 10000, 'paymentstatus', true)
      ]);

      const newStats = {
        totalCustomers: customerStats.data?.total || 0,
        activeCustomers: customerStats.data?.active || 0,
        monthlyRevenue: paymentStats.data?.monthCollection || 0,
        todayCollection: paymentStats.data?.todayCollection || 0,
        pendingBills: billsResult.data?.filter(b => b.paymentstatus === 'Unpaid').length || 0,
        overdueAccounts: 0 // Will be calculated
      };

      // Calculate overdue accounts (bills from 2+ months ago still unpaid)
      const twoMonthsAgo = new Date();
      twoMonthsAgo.setMonth(twoMonthsAgo.getMonth() - 2);
      const overdueCustomerIds = new Set(
        billsResult.data
          ?.filter(b => b.paymentstatus === 'Unpaid' && new Date(b.billedmonth) < twoMonthsAgo)
          .map(b => b.customerid) || []
      );
      newStats.overdueAccounts = overdueCustomerIds.size;

      setStats(newStats);
    } catch (err) {
      console.error('Error loading statistics:', err);
    }
    setStatsLoading(false);
  };

  const StatCard = ({ title, value, subtext, icon, color, bgcolor }) => (
    <Card sx={{ height: '100%' }}>
      <CardContent>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <Box>
            <Typography color="textSecondary" gutterBottom variant="overline">
              {title}
            </Typography>
            <Typography variant="h4" component="div" fontWeight="bold">
              {statsLoading ? <CircularProgress size={24} /> : value}
            </Typography>
            <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
              {subtext}
            </Typography>
          </Box>
          <Avatar sx={{ bgcolor: bgcolor, color: color, width: 56, height: 56 }}>
            {icon}
          </Avatar>
        </Box>
      </CardContent>
    </Card>
  );

  return (
    <Box>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" fontWeight="bold" gutterBottom>
          Dashboard
        </Typography>
        <Typography variant="subtitle1" color="text.secondary">
          Welcome back, {user?.firstname}! Here's your system overview.
        </Typography>
      </Box>

      {/* Statistics Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Total Customers"
            value={stats.totalCustomers.toLocaleString()}
            subtext={`${stats.activeCustomers} Active`}
            icon={<People />}
            color="#1976d2"
            bgcolor="#e3f2fd"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Monthly Revenue"
            value={`₱${stats.monthlyRevenue.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`}
            subtext={`₱${stats.todayCollection.toLocaleString('en-PH', { minimumFractionDigits: 2 })} Today`}
            icon={<MonetizationOn />}
            color="#2e7d32"
            bgcolor="#e8f5e9"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Pending Bills"
            value={stats.pendingBills.toLocaleString()}
            subtext="Awaiting Payment"
            icon={<Receipt />}
            color="#ed6c02"
            bgcolor="#fff3e0"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            title="Overdue Accounts"
            value={stats.overdueAccounts.toLocaleString()}
            subtext="2+ Months Behind"
            icon={<Warning />}
            color="#d32f2f"
            bgcolor="#ffebee"
          />
        </Grid>
      </Grid>

      {/* Quick Actions */}
      <Card sx={{ mb: 4 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Bolt color="primary" /> Quick Actions
          </Typography>
          <Grid container spacing={1.5}>
            <Grid item xs={12} sm="auto">
              <Button fullWidth variant="contained" startIcon={<PersonAdd />} onClick={() => navigate('/portal/water-billing/customers')}>
                Add Customer
              </Button>
            </Grid>
            <Grid item xs={12} sm="auto">
              <Button fullWidth variant="contained" color="info" startIcon={<Description />} onClick={() => navigate('/portal/water-billing/billing')}>
                Create Bill
              </Button>
            </Grid>
            <Grid item xs={12} sm="auto">
              <Button fullWidth variant="contained" color="success" startIcon={<Payment />} onClick={() => navigate('/portal/water-billing/payments')}>
                Record Payment
              </Button>
            </Grid>
            <Grid item xs={12} sm="auto">
              <Button fullWidth variant="contained" color="secondary" startIcon={<Assessment />} onClick={() => navigate('/portal/water-billing/reports')}>
                View Reports
              </Button>
            </Grid>
            <Grid item xs={12} sm="auto">
              <Button fullWidth variant="outlined" color="warning" startIcon={<Refresh />} onClick={loadStatistics}>
                Refresh Stats
              </Button>
            </Grid>
          </Grid>

        </CardContent>
      </Card>

      {/* Recent Activities Section */}
      <Grid container spacing={3}>
        {/* Recent Customers */}
        <Grid item xs={12} md={6}>
          <Card sx={{ height: '100%' }}>
            <Box sx={{ p: 2, bgcolor: 'primary.main', color: 'primary.contrastText' }}>
              <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <People fontSize="small" /> Recent Customers
              </Typography>
            </Box>
            <List dense>
              {loading ? (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                  <CircularProgress />
                </Box>
              ) : recentCustomers.length === 0 ? (
                <ListItem>
                  <ListItemText primary="No recent customers" sx={{ textAlign: 'center', color: 'text.secondary' }} />
                </ListItem>
              ) : (
                recentCustomers.map((customer, index) => (
                  <React.Fragment key={customer.customerid}>
                    <ListItemButton onClick={() => setSelectedCustomer(customer)}>
                      <ListItemAvatar>
                        <Avatar sx={{ bgcolor: 'primary.light' }}><Person /></Avatar>
                      </ListItemAvatar>
                      <ListItemText
                        primary={customer.name}
                        secondary={
                          <React.Fragment>
                            <Typography component="span" variant="body2" color="text.primary">
                              {customer.type}
                            </Typography>
                            {` — ${customer.address ? `${customer.address}, ${customer.barangay || ''}`.trim().replace(/(, )+$/, '') : (customer.barangay || 'No address')}`}
                          </React.Fragment>
                        }
                      />
                      <ChevronRight color="action" />
                    </ListItemButton>
                    {index < recentCustomers.length - 1 && <Divider variant="inset" component="li" />}
                  </React.Fragment>
                ))
              )}
            </List>
          </Card>
        </Grid>

        {/* Recent Payments */}
        <Grid item xs={12} md={6}>
          <Card sx={{ height: '100%' }}>
            <Box sx={{ p: 2, bgcolor: 'success.main', color: 'success.contrastText' }}>
              <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Payment fontSize="small" /> Recent Payments
              </Typography>
            </Box>
            <List dense>
              {loading ? (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
                  <CircularProgress />
                </Box>
              ) : recentPayments.length === 0 ? (
                <ListItem>
                  <ListItemText primary="No recent payments" sx={{ textAlign: 'center', color: 'text.secondary' }} />
                </ListItem>
              ) : (
                recentPayments.map((payment, index) => (
                  <React.Fragment key={payment.billid}>
                    <ListItemButton onClick={() => setSelectedPayment(payment)}>
                      <ListItemAvatar>
                        <Avatar sx={{ bgcolor: 'success.light' }}><CheckCircle /></Avatar>
                      </ListItemAvatar>
                      <ListItemText
                        primary={payment.customer?.name || 'Unknown'}
                        secondary={new Date(payment.datepaid).toLocaleDateString()}
                      />
                      <Typography variant="body2" color="success.main" fontWeight="bold">
                        ₱{payment.totalbillamount?.toFixed(2)}
                      </Typography>
                    </ListItemButton>
                    {index < recentPayments.length - 1 && <Divider variant="inset" component="li" />}
                  </React.Fragment>
                ))
              )}
            </List>
          </Card>
        </Grid>
      </Grid>

      {/* Customer Detail Modal */}
      <Dialog open={Boolean(selectedCustomer)} onClose={() => setSelectedCustomer(null)} maxWidth="sm" fullWidth>
        <DialogTitle>
          Customer Details
          <IconButton
            aria-label="close"
            onClick={() => setSelectedCustomer(null)}
            sx={{ position: 'absolute', right: 8, top: 8, color: (theme) => theme.palette.grey[500] }}
          >
            <Close />
          </IconButton>
        </DialogTitle>
        <DialogContent dividers>
          {selectedCustomer && (
            <Grid container spacing={2}>
              <Grid item xs={12}><TextField fullWidth label="Customer ID" value={selectedCustomer.customerid} InputProps={{ readOnly: true }} variant="outlined" /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Name" value={selectedCustomer.name} InputProps={{ readOnly: true }} variant="outlined" /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Type" value={selectedCustomer.type || 'N/A'} InputProps={{ readOnly: true }} variant="outlined" /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Address" value={selectedCustomer.address || 'N/A'} InputProps={{ readOnly: true }} variant="outlined" /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Barangay" value={selectedCustomer.barangay || 'N/A'} InputProps={{ readOnly: true }} variant="outlined" /></Grid>
              <Grid item xs={6}>
                <Typography variant="subtitle2" gutterBottom>Status</Typography>
                <Chip label={selectedCustomer.status || 'N/A'} color={selectedCustomer.status === 'Active' ? 'success' : 'error'} />
              </Grid>
              <Grid item xs={6}><TextField fullWidth label="Date Added" value={selectedCustomer.date_added || 'N/A'} InputProps={{ readOnly: true }} variant="outlined" /></Grid>
            </Grid>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSelectedCustomer(null)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Payment Detail Modal */}
      <Dialog open={Boolean(selectedPayment)} onClose={() => setSelectedPayment(null)} maxWidth="sm" fullWidth>
        <DialogTitle>
          Payment Details
          <IconButton
            aria-label="close"
            onClick={() => setSelectedPayment(null)}
            sx={{ position: 'absolute', right: 8, top: 8, color: (theme) => theme.palette.grey[500] }}
          >
            <Close />
          </IconButton>
        </DialogTitle>
        <DialogContent dividers>
          {selectedPayment && (
            <Grid container spacing={2}>
              <Grid item xs={12}><TextField fullWidth label="Bill ID" value={selectedPayment.billid} InputProps={{ readOnly: true }} /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Customer" value={selectedPayment.customer?.name || 'Unknown'} InputProps={{ readOnly: true }} /></Grid>
              <Grid item xs={6}><TextField fullWidth label="Billed Month" value={selectedPayment.billedmonth || 'N/A'} InputProps={{ readOnly: true }} /></Grid>
              <Grid item xs={6}><TextField fullWidth label="Payment Date" value={selectedPayment.datepaid ? new Date(selectedPayment.datepaid).toLocaleDateString() : 'N/A'} InputProps={{ readOnly: true }} /></Grid>
              <Grid item xs={6}><TextField fullWidth label="Basic Amount" value={`₱${selectedPayment.basicamount?.toFixed(2) || '0.00'}`} InputProps={{ readOnly: true }} /></Grid>
              <Grid item xs={6}><TextField fullWidth label="Surcharge" value={`₱${selectedPayment.surchargeamount?.toFixed(2) || '0.00'}`} InputProps={{ readOnly: true }} /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Total Amount" value={`₱${selectedPayment.totalbillamount?.toFixed(2) || '0.00'}`} InputProps={{ readOnly: true }} sx={{ input: { fontWeight: 'bold' } }} /></Grid>
              <Grid item xs={12}><TextField fullWidth label="Processed By" value={selectedPayment.paidby || 'N/A'} InputProps={{ readOnly: true }} /></Grid>
              {selectedPayment.advancepaymentamount && selectedPayment.advancepaymentamount > 0 && (
                <Grid item xs={12}><TextField fullWidth label="Credit Applied" value={`₱${selectedPayment.advancepaymentamount?.toFixed(2)}`} InputProps={{ readOnly: true }} /></Grid>
              )}
            </Grid>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSelectedPayment(null)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default DashboardHome;
